echo "import json
import os

# Read configuration
with open('/app/project_config.json', 'r') as f:
    config = json.load(f)

# Validate configuration
required_fields = ['project_name', 'target_type', 'sources', 'headers', 'compiler', 'standard', 'optimization', 'include_dirs', 'library_dirs', 'libraries', 'defines', 'warnings', 'output_dir', 'clean_patterns']

errors = []
for field in required_fields:
    if field not in config:
        errors.append(f'Missing required field: {field}')

if config['target_type'] not in ['executable', 'static_lib', 'shared_lib']:
    errors.append('Invalid target_type')

for source in config['sources']:
    if not source.endswith('.cpp'):
        errors.append(f'Invalid source file: {source} (must end with .cpp)')

# Write Makefile
with open('/app/Makefile', 'w') as f:
    f.write('## Generated Makefile for {config['project_name']}

')
    f.write(f'PROJECT_NAME = {config['project_name']}
')
    f.write(f'TARGET_TYPE = {config['target_type']}
')
    f.write(f'SOURCES = {config['sources']}
')
    f.write(f'HEADERS = {config['headers']}
')
    f.write(f'COMPILER = {config['compiler']}
')
    f.write(f'CXXSTD = {config['standard']}
')
    f.write(f'OPTIMIZATION = {config['optimization']}
')
    f.write(f'INCLUDE_DIRS = {config['include_dirs']}
')
    f.write(f'LIBRARY_DIRS = {config['library_dirs']}
')
    f.write(f'LIBRARIES = {config['libraries']}
')
    f.write(f'DEFINES = {config['defines']}
')
    f.write(f'WARNINGS = {config['warnings']}
')
    f.write(f'OUTPUT_DIR = {config['output_dir']}
')
    f.write(f'CLEAN_PATTERNS = {config['clean_patterns']}

')
    f.write('ifeq ($(OPTIMIZATION), debug)
')
    f.write('CFLAGS += -g
')
    f.write('else
')
    f.write('CFLAGS += -O2
')
    f.write('endif

')
    f.write('all: $(PROJECT_NAME)

')
    f.write('$(PROJECT_NAME): $(SOURCES:.cpp=.o)
')
    f.write('	$(COMPILER) $(CFLAGS) $(CXXSTD) $(DEFINES) -I$(INCLUDE_DIRS) -L$(LIBRARY_DIRS) -o $@ $^ $(LIBRARIES)

')
    f.write('%.o: %.cpp
')
    f.write('	$(COMPILER) $(CFLAGS) $(CXXSTD) $(DEFINES) -I$(INCLUDE_DIRS) -c $< -o $@

')
    f.write('clean:
')
    f.write('	rm -f $(CLEAN_PATTERNS)

')
    f.write('.PHONY: all clean
')

# Write test program
with open('/app/test_program.cpp', 'w') as f:
    f.write('#include <iostream>
#include "include/math.h"

#define DEBUG 1

int main() {
    std::cout << "Test program for {config['project_name']}
";
    std::cout << "Using define: DEBUG = " << DEBUG << std::endl;
    return 0;
}

# Write generation report
report = {
    'status': 'success' if len(errors) == 0 else 'failure',
    'errors': errors,
    'generated_targets': ['Makefile', 'test_program.cpp'],
    'variables_defined': ['PROJECT_NAME', 'TARGET_TYPE', 'SOURCES', 'HEADERS', 'COMPILER', 'CXXSTD', 'OPTIMIZATION', 'INCLUDE_DIRS', 'LIBRARY_DIRS', 'LIBRARIES', 'DEFINES', 'WARNINGS', 'OUTPUT_DIR', 'CLEAN_PATTERNS'],
    'validation_passed': len(errors) == 0
}

with open('/app/generation_report.json', 'w') as f:
    json.dump(report, f, indent=4)
" > generate_makefile.py
